package org.apache.commons.math3.optim.nonlinear.vector;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.linear.DiagonalMatrix;
import org.apache.commons.math3.linear.MatrixUtils;
import org.apache.commons.math3.linear.NonSquareMatrixException;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.optim.OptimizationData;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Weight constructor and related methods.
 */
public class Weight_Weight_TriageGen1Test {

    @Test
    public void testConstructorWithDoubleArray() {
        double[] weightArray = {1.0, 2.5, 3.0};
        Weight weight = new Weight(weightArray);
        RealMatrix matrix = weight.getWeight();

        // Verify dimensions
        Assert.assertEquals(3, matrix.getRowDimension());
        Assert.assertEquals(3, matrix.getColumnDimension());

        // Verify diagonal elements
        Assert.assertEquals(1.0, matrix.getEntry(0, 0), 1e-10);
        Assert.assertEquals(2.5, matrix.getEntry(1, 1), 1e-10);
        Assert.assertEquals(3.0, matrix.getEntry(2, 2), 1e-10);

        // Verify non-diagonal elements are zero
        Assert.assertEquals(0.0, matrix.getEntry(0, 1), 1e-10);
        Assert.assertEquals(0.0, matrix.getEntry(1, 0), 1e-10);
        Assert.assertEquals(0.0, matrix.getEntry(0, 2), 1e-10);
        Assert.assertEquals(0.0, matrix.getEntry(2, 0), 1e-10);
    }








}

