/**
 * Unit tests for Weight constructor and related methods.
 */
public class Weight_Weight_TriageGen1Test {









    @Test
    public void testGetWeightReturnsSameMatrixInstanceOrEquivalent() {
        double[] weightArray = {5.0};
        Weight weight = new Weight(weightArray);
        RealMatrix matrix1 = weight.getWeight();
        RealMatrix matrix2 = weight.getWeight();

        Assert.assertNotNull(matrix1);
        Assert.assertEquals(5.0, matrix1.getEntry(0, 0), 1e-10);
        // Depending on implementation, it might be the same instance or an equivalent one.
        // Given the code, it returns the internal field.
        Assert.assertSame(matrix1, matrix2);
    }
